// The first cell of the sheet (A1) is used by n8n as a column header.
// It contains the forecast version name, e.g. 'forecast ABR'.
// We extract that, convert to N+M notation, and tag every row.

const items = $input.all();
if (items.length === 0) return [{ json: { content: '[]' } }];

const monthMap = {
  'jan': '0+12', 'fev': '1+11', 'mar': '2+10', 'abr': '3+9',
  'mai': '4+8', 'jun': '5+7', 'jul': '6+6', 'ago': '7+5',
  'set': '8+4', 'out': '9+3', 'nov': '10+2', 'dez': '11+1'
};

// Find the column whose name starts with 'forecast ' — that's the version cell
const allKeys = Object.keys(items[0].json);
const versionKey = allKeys.find(k => String(k).toLowerCase().trim().startsWith('forecast '));

let versionLabel = null; // null = fall back to 'Forecast YYYY' in dashboard
if (versionKey) {
  const rest = versionKey.substring(9).trim(); // remove 'forecast ' prefix
  const parts = rest.split(/\s+/);
  const monthKey = parts[0].toLowerCase(); // e.g. 'abr'
  const suffix = parts.slice(1).join(' ');  // e.g. 'v2' or ''
  const nm = monthMap[monthKey];
  if (nm) {
    versionLabel = suffix ? `Forecast ${nm} ${suffix}` : `Forecast ${nm}`;
  }
}

// Tag every row with _version (only if resolved)
const tagged = items.map(item => {
  const row = { ...item.json };
  if (versionLabel) row._version = versionLabel;
  return row;
});
return [{ json: { content: JSON.stringify(tagged) } }];
